-- ============================================================================
-- PROJECT: Waste2Menu — A Zero-Waste Reverse Recipe & Byproduct Optimization Engine
-- SEED DATASET (PostgreSQL / pgAdmin 4)
-- Contains 6 Categories, 35 Scraps (Complete Matrix), 35 Recipes, 4 Chennai Dispatches & Demo Users
-- ============================================================================

TRUNCATE TABLE ngo_dispatches, recipes, byproduct_scraps, scrap_categories, users RESTART IDENTITY CASCADE;

-- 1. INSERT DEMO USERS (Master Chef, Home Chef, NGO Rep)
SELECT setval('users_id_seq', (SELECT MAX(id) FROM users));

-- 2. INSERT 6 SCRAP CATEGORIES
SELECT setval('scrap_categories_id_seq', (SELECT MAX(id) FROM scrap_categories));

-- 3. INSERT 35 BYPRODUCT SCRAPS (Complete 6-Category Matrix)
SELECT setval('byproduct_scraps_id_seq', (SELECT MAX(id) FROM byproduct_scraps));

-- 4. INSERT 35 VERIFIED TRADITIONAL & MASTER CHEF RECIPES
SELECT setval('recipes_id_seq', (SELECT MAX(id) FROM recipes));

-- 5. INSERT 4 SAMPLE NGO DISPATCHES (100% CHENNAI SURPLUS FEED)
SELECT setval('ngo_dispatches_id_seq', (SELECT MAX(id) FROM ngo_dispatches));
